SELECT a.id AS applyId, a.period_id AS periodId, p.title AS periodTitle, a.item_id AS itemId, i.name AS itemName, a.title, a.amount, a.expect_date AS expectDate, a.attach_file_id AS attachFileId, a.status, u.real_name AS auditUserName, a.audit_time AS auditTime, a.audit_remark AS auditRemark, a.create_time AS createTime FROM budget_apply a LEFT JOIN budget_period p ON a.period_id = p.id LEFT JOIN budget_item i ON a.item_id = i.id LEFT JOIN sys_user u ON a.audit_user_id = u.id WHERE a.apply_user_id = #{applyUserId} AND a.deleted = 0
AND a.status = #{status}
AND a.period_id = #{periodId}
AND a.create_time >= #{beginTime}
AND a.create_time <= #{endTime}
ORDER BY a.create_time DESC LIMIT #{offset}, #{pageSize}

SELECT COUNT(*)
FROM budget_apply a
WHERE a.apply_user_id = #{applyUserId}
  AND a.deleted = 0

    AND a.status = #{status}


    AND a.period_id = #{periodId}


    AND a.create_time >= #{beginTime}


    AND a.create_time <= #{endTime}

SELECT
    COUNT(*) AS applyTotal,
    COALESCE(SUM(a.amount), 0) AS applyAmount,
    COALESCE(SUM(CASE WHEN a.status = 1 THEN 1 ELSE 0 END), 0) AS approvedCount,
    COALESCE(SUM(CASE WHEN a.status = 1 THEN a.amount ELSE 0 END), 0) AS approvedAmount,
    COALESCE(SUM(CASE WHEN a.status = 2 THEN 1 ELSE 0 END), 0) AS rejectedCount,
    COALESCE(SUM(CASE WHEN a.status = 0 THEN 1 ELSE 0 END), 0) AS pendingCount,
    COALESCE(SUM(CASE WHEN a.status = 3 THEN 1 ELSE 0 END), 0) AS cancelledCount,
    COALESCE((
        SELECT SUM(e.amount)
        FROM budget_expense e
        INNER JOIN budget_apply a2 ON e.apply_id = a2.id AND a2.deleted = 0
        WHERE a2.apply_user_id = #{applyUserId}
          AND a2.create_time >= #{beginTime}
          AND a2.create_time < #{endTime}
          AND e.deleted = 0
    ), 0) AS expenseAmount
FROM budget_apply a
WHERE a.apply_user_id = #{applyUserId}
  AND a.deleted = 0
  AND a.create_time >= #{beginTime}
  AND a.create_time < #{endTime}

SELECT a.id AS applyId, a.period_id AS periodId, p.title AS periodTitle, a.item_id AS itemId, i.name AS itemName, a.apply_user_id AS applyUserId, au.real_name AS applyUserName, au.grade AS grade, a.title, a.amount, a.reason, a.expect_date AS expectDate, a.attach_file_id AS attachFileId, a.status, a.audit_user_id AS auditUserId, u.real_name AS auditUserName, a.audit_time AS auditTime, a.audit_remark AS auditRemark, a.create_time AS createTime FROM budget_apply a LEFT JOIN budget_period p ON a.period_id = p.id LEFT JOIN budget_item i ON a.item_id = i.id LEFT JOIN sys_user au ON a.apply_user_id = au.id LEFT JOIN sys_user u ON a.audit_user_id = u.id WHERE a.deleted = 0
AND a.status = #{status}
AND a.period_id = #{periodId}
AND a.item_id = #{itemId}
AND a.apply_user_id = #{applyUserId}
AND (a.title LIKE CONCAT('%', #{keyword}, '%') OR au.real_name LIKE CONCAT('%', #{keyword}, '%'))
AND a.create_time >= #{beginTime}
AND a.create_time <= #{endTime}
ORDER BY a.create_time DESC LIMIT #{offset}, #{pageSize}

SELECT COUNT(*)
FROM budget_apply a
LEFT JOIN sys_user au ON a.apply_user_id = au.id
WHERE a.deleted = 0

    AND a.status = #{status}


    AND a.period_id = #{periodId}


    AND a.item_id = #{itemId}


    AND a.apply_user_id = #{applyUserId}


    AND (a.title LIKE CONCAT('%', #{keyword}, '%')
         OR au.real_name LIKE CONCAT('%', #{keyword}, '%'))


    AND a.create_time >= #{beginTime}


    AND a.create_time <= #{endTime}
